use std::collections::HashMap;
use std::env;
use std::fs;
use std::io::{self, Write};
use std::path::PathBuf;
use std::process::{self, Command};

use clap::{App, Arg, SubCommand};
use indexmap::IndexMap;
use serde::{Deserialize, Serialize};

#[derive(Debug, Serialize, Deserialize, Clone, Default)]
struct Script {
    command: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    description: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    tags: Option<Vec<String>>,
}

#[derive(Debug, Serialize, Deserialize, Default)]
struct Config {
    #[serde(default)]
    scripts: IndexMap<String, Script>,
    #[serde(default)]
    default: DefaultConfig,
}

#[derive(Debug, Serialize, Deserialize, Default, Clone)]
struct DefaultConfig {
    #[serde(skip_serializing_if = "Option::is_none")]
    cmd_width: Option<usize>,
}

fn find_default_config() -> Option<PathBuf> {
    // Priority order:
    // 1. $PIER_CONFIG_PATH (already handled)
    // 2. pier.toml (in current directory)
    // 3. $XDG_CONFIG_HOME/pier/config.toml
    // 4. $XDG_CONFIG_HOME/pier/config
    // 5. $XDG_CONFIG_HOME/pier.toml
    // 6. $HOME/.pier.toml
    // 7. $HOME/.pier

    let cwd_pier_toml = PathBuf::from("pier.toml");
    if cwd_pier_toml.exists() {
        return Some(cwd_pier_toml);
    }

    let xdg_config_home = env::var("XDG_CONFIG_HOME").ok().map(PathBuf::from);

    if let Some(ref xdg) = xdg_config_home {
        let p = xdg.join("pier/config.toml");
        if p.exists() {
            return Some(p);
        }
        let p = xdg.join("pier/config");
        if p.exists() {
            return Some(p);
        }
        let p = xdg.join("pier.toml");
        if p.exists() {
            return Some(p);
        }
    }

    let home = env::var("HOME").ok().map(PathBuf::from);
    if let Some(ref h) = home {
        let p = h.join(".pier.toml");
        if p.exists() {
            return Some(p);
        }
        let p = h.join(".pier");
        if p.exists() {
            return Some(p);
        }
    }

    None
}

fn read_config(path: &PathBuf) -> Result<Config, String> {
    let content = fs::read_to_string(path)
        .map_err(|e| format!("Unable to read config from file {}: {}", path.display(), e))?;
    toml::from_str(&content)
        .map_err(|e| format!("Failed to parse config: {}", e))
}

fn write_config(path: &PathBuf, config: &Config) -> Result<(), String> {
    let content = toml::to_string_pretty(config)
        .map_err(|e| format!("Failed to serialize config: {}", e))?;

    // We need to write in the specific format the original uses
    // Scripts must be in sorted order, with specific formatting
    fs::write(path, content)
        .map_err(|e| format!("Failed to write config: {}", e))
}

fn serialize_config(config: &Config) -> Result<String, String> {
    // Custom serialization to match original format
    let mut output = String::new();

    // Write scripts in sorted order
    let mut scripts: Vec<(&String, &Script)> = config.scripts.iter().collect();
    scripts.sort_by_key(|(k, _)| k.as_str());

    for (alias, script) in &scripts {
        output.push_str(&format!("[scripts.{}]\n", alias));
        // command uses single quotes
        output.push_str(&format!("command = '{}'\n", script.command));
        if let Some(ref desc) = script.description {
            output.push_str(&format!("description = '{}'\n", desc));
        }
        if let Some(ref tags) = script.tags {
            output.push_str("tags = [\n");
            for tag in tags {
                output.push_str(&format!("    '{}',\n", tag));
            }
            output.push_str("]\n");
        }
        output.push('\n');
    }

    output.push_str("[default]\n");
    if let Some(w) = config.default.cmd_width {
        output.push_str(&format!("cmd_width = {}\n", w));
    }

    Ok(output)
}

fn error_exit(msg: &str) -> ! {
    eprintln!("error: {}", msg);
    process::exit(1);
}

fn print_table(scripts: &IndexMap<String, Script>, cmd_width: Option<usize>) {
    // Headers
    let alias_header = "Alias";
    let tags_header = "Tags";
    let cmd_header = "Command";
    let desc_header = "Description";

    // Calculate column widths
    let alias_width = scripts.keys()
        .map(|k| k.len())
        .max()
        .unwrap_or(0)
        .max(alias_header.len());

    let tags_width = scripts.values()
        .map(|s| {
            s.tags.as_ref()
                .map(|t| t.join(",").len())
                .unwrap_or(0)
        })
        .max()
        .unwrap_or(0)
        .max(tags_header.len());

    let raw_cmd_width = scripts.values()
        .map(|s| s.command.len())
        .max()
        .unwrap_or(0)
        .max(cmd_header.len());

    let cmd_col_width = if let Some(w) = cmd_width {
        w.max(cmd_header.len())
    } else {
        raw_cmd_width
    };

    let desc_width = scripts.values()
        .map(|s| s.description.as_ref().map(|d| d.len()).unwrap_or(0))
        .max()
        .unwrap_or(0)
        .max(desc_header.len());

    // Total line width: each col adds 2 spaces (1 on each side) + 1 separator char + 1 at start
    // Format: ⋮ col1 ⋮ col2 ⋮ col3 ⋮ col4 ⋮
    // Each column: " " + content + padding + " " between separators
    let total_width = 1 + (alias_width + 2) + 1 + (tags_width + 2) + 1 + (cmd_col_width + 2) + 1 + (desc_width + 2) + 1;

    let sep_char = "≖";
    let sep_line = sep_char.repeat(total_width);
    let vert = "⋮";

    println!("{}", sep_line);

    // Header row
    println!("{} {:<aw$} {} {:<tw$} {} {:<cw$} {} {:<dw$} {}",
        vert,
        alias_header,
        vert,
        tags_header,
        vert,
        cmd_header,
        vert,
        desc_header,
        vert,
        aw = alias_width,
        tw = tags_width,
        cw = cmd_col_width,
        dw = desc_width,
    );

    println!("{}", sep_line);

    // Data rows
    for (alias, script) in scripts.iter() {
        let tags_str = script.tags.as_ref()
            .map(|t| t.join(","))
            .unwrap_or_default();

        let cmd = if let Some(w) = cmd_width {
            let c: String = script.command.chars().take(w).collect();
            c
        } else {
            script.command.clone()
        };

        let desc = script.description.as_deref().unwrap_or("");

        println!("{} {:<aw$} {} {:<tw$} {} {:<cw$} {} {:<dw$} {}",
            vert,
            alias,
            vert,
            tags_str,
            vert,
            cmd,
            vert,
            desc,
            vert,
            aw = alias_width,
            tw = tags_width,
            cw = cmd_col_width,
            dw = desc_width,
        );
    }

    println!("{}", sep_line);
}

fn main() {
    let app = App::new("pier")
        .version("0.1.6")
        .author("Benjamin Scholtz, Isak Johansson")
        .about("A simple script management CLI")
        .arg(Arg::with_name("config")
            .short("c")
            .long("config-file")
            .value_name("path")
            .help("Sets a custom config file.\n\nDEFAULT PATH is otherwise determined in this order:\n\n- $PIER_CONFIG_PATH (environment variable if set)\n\n- pier.toml (in the current directory)\n\n- $XDG_CONFIG_HOME/pier/config.toml\n\n- $XDG_CONFIG_HOME/pier/config\n\n- $XDG_CONFIG_HOME/pier.toml\n\n- $HOME/.pier.toml\n\n- $HOME/.pier\n\n")
            .takes_value(true)
            .env("PIER_CONFIG_PATH"))
        .arg(Arg::with_name("verbose")
            .short("v")
            .long("verbose")
            .help("The level of verbosity"))
        .arg(Arg::with_name("alias")
            .value_name("alias")
            .help("The alias or name for the script.")
            .index(1))
        .arg(Arg::with_name("args")
            .value_name("args")
            .help("The positional arguments to send to script.")
            .multiple(true)
            .index(2))
        .subcommand(SubCommand::with_name("add")
            .about("Add a new script to config.")
            .arg(Arg::with_name("alias")
                .short("a")
                .long("alias")
                .value_name("alias")
                .help("The alias or name for the script.")
                .required(true)
                .takes_value(true))
            .arg(Arg::with_name("description")
                .short("d")
                .long("description")
                .value_name("description")
                .help("The description for the script.")
                .takes_value(true))
            .arg(Arg::with_name("tags")
                .short("t")
                .long("tag")
                .value_name("tags")
                .help("Set which tags the script belongs to.")
                .multiple(true)
                .takes_value(true))
            .arg(Arg::with_name("force")
                .short("f")
                .long("force")
                .help("Allows to overwrite the existing script"))
            .arg(Arg::with_name("command")
                .value_name("command")
                .help("The command/script content to be executed. If this argument is not found it will open your $EDITOR\nfor you to enter the script into.")
                .index(1)))
        .subcommand(SubCommand::with_name("list")
            .about("alias: ls - List scripts\n\nDisplay options are determined by priority in this order:\n\n1. List only aliases\n\n2. Show full command\n\n3. Command display with (cli option)\n\n4. Command display with (config option)")
            .alias("ls")
            .arg(Arg::with_name("list_aliases")
                .short("q")
                .long("list_aliases")
                .help("Only displays aliases of the scripts."))
            .arg(Arg::with_name("cmd_full")
                .short("l")
                .long("cmd_full")
                .help("Display the full command."))
            .arg(Arg::with_name("cmd_width")
                .short("c")
                .long("cmd_width")
                .value_name("cmd-width")
                .help("The max number of characters to display from the command.")
                .takes_value(true))
            .arg(Arg::with_name("tags")
                .short("t")
                .long("tag")
                .value_name("tags")
                .help("Filter based on tags.")
                .multiple(true)
                .takes_value(true)))
        .subcommand(SubCommand::with_name("run")
            .about("Run a script matching alias.")
            .arg(Arg::with_name("alias")
                .value_name("alias")
                .help("The alias or name for the script.")
                .required(true)
                .index(1))
            .arg(Arg::with_name("args")
                .value_name("args")
                .help("The positional arguments to send to script.")
                .multiple(true)
                .index(2)))
        .subcommand(SubCommand::with_name("remove")
            .about("alias: rm - Remove a script matching alias.")
            .alias("rm")
            .arg(Arg::with_name("alias")
                .value_name("alias")
                .help("The alias or name for the script.")
                .required(true)
                .index(1)))
        .subcommand(SubCommand::with_name("edit")
            .about("Edit a script matching alias.")
            .arg(Arg::with_name("alias")
                .value_name("alias")
                .help("The alias or name for the script.")
                .required(true)
                .index(1)))
        .subcommand(SubCommand::with_name("show")
            .about("Show a script matching alias.")
            .arg(Arg::with_name("alias")
                .value_name("alias")
                .help("The alias or name for the script.")
                .required(true)
                .index(1)))
        .subcommand(SubCommand::with_name("copy")
            .about("alias: cp - Copy existing alias to the new one")
            .alias("cp")
            .arg(Arg::with_name("from-alias")
                .value_name("from-alias")
                .help("The alias of the script that will be copied.")
                .required(true)
                .index(1))
            .arg(Arg::with_name("to-alias")
                .value_name("to-alias")
                .help("The new alias of the copy of the script.")
                .required(true)
                .index(2)))
        .subcommand(SubCommand::with_name("move")
            .about("alias: mv, rename - Move/rename existing alias to the new one")
            .aliases(&["mv", "rename"])
            .arg(Arg::with_name("force")
                .short("f")
                .long("force")
                .help("Allows to overwrite the existing script"))
            .arg(Arg::with_name("from-alias")
                .value_name("from-alias")
                .help("The alias of the script that will be moved.")
                .required(true)
                .index(1))
            .arg(Arg::with_name("to-alias")
                .value_name("to-alias")
                .help("The new alias of the script.")
                .required(true)
                .index(2)))
        .subcommand(SubCommand::with_name("config-init")
            .about("alias: init - Add a config file.")
            .alias("init"));

    let matches = app.get_matches();

    let verbose = matches.is_present("verbose");

    // Get config path
    let config_path: Option<PathBuf> = matches.value_of("config").map(PathBuf::from);

    match matches.subcommand() {
        ("config-init", Some(_sub)) => {
            let path = if let Some(p) = config_path {
                p
            } else {
                // Default to $HOME/.pier.toml
                let home = env::var("HOME").unwrap_or_else(|_| ".".to_string());
                PathBuf::from(home).join(".pier.toml")
            };

            if path.exists() {
                error_exit(&format!("Cannot initialize config at {}, file already exists.", path.display()));
            }

            // Create parent directory if needed
            if let Some(parent) = path.parent() {
                if !parent.exists() && parent != std::path::Path::new("") {
                    fs::create_dir_all(parent)
                        .unwrap_or_else(|e| error_exit(&format!("Failed to create directory: {}", e)));
                }
            }

            let init_config = "[scripts.hello-pier]\ncommand = 'echo Hello, Pier!'\ndescription = 'This is an example command.'\n\n[default]\n";
            fs::write(&path, init_config)
                .unwrap_or_else(|e| error_exit(&format!("Failed to write config: {}", e)));
            println!("Added hello-pier");
        },

        ("add", Some(sub)) => {
            let path = get_config_path(config_path);
            let mut config = read_config(&path)
                .unwrap_or_else(|e| error_exit(&e));

            let alias = sub.value_of("alias").unwrap();
            let force = sub.is_present("force");

            if config.scripts.contains_key(alias) && !force {
                error_exit(&format!("AliasAlreadyExists:  {}", alias));
            }

            let command = if let Some(cmd) = sub.value_of("command") {
                cmd.to_string()
            } else {
                // Open editor
                open_editor().unwrap_or_else(|e| error_exit(&e))
            };

            let description = sub.value_of("description").map(String::from);
            let tags: Option<Vec<String>> = sub.values_of("tags").map(|v| v.map(String::from).collect());

            let script = Script {
                command,
                description,
                tags,
            };

            config.scripts.insert(alias.to_string(), script);

            let content = serialize_config(&config)
                .unwrap_or_else(|e| error_exit(&e));
            fs::write(&path, content)
                .unwrap_or_else(|e| error_exit(&format!("Failed to write config: {}", e)));

            println!("Added {}", alias);
        },

        ("list", Some(sub)) | ("ls", Some(sub)) => {
            let path = get_config_path(config_path);
            let config = read_config(&path)
                .unwrap_or_else(|e| error_exit(&e));

            if config.scripts.is_empty() {
                error_exit("No scripts exist. Would you like to add a new script?");
            }

            let filter_tags: Option<Vec<&str>> = sub.values_of("tags").map(|v| v.collect());

            let mut scripts: IndexMap<String, Script> = config.scripts.clone();

            // Filter by tags if specified
            if let Some(ref tags) = filter_tags {
                scripts.retain(|_, s| {
                    if let Some(ref script_tags) = s.tags {
                        tags.iter().all(|t| script_tags.contains(&t.to_string()))
                    } else {
                        false
                    }
                });
            }

            // Sort by alias
            let mut sorted: Vec<(String, Script)> = scripts.into_iter().collect();
            sorted.sort_by_key(|(k, _)| k.clone());
            let scripts: IndexMap<String, Script> = sorted.into_iter().collect();

            if sub.is_present("list_aliases") {
                // Only display aliases
                for alias in scripts.keys() {
                    println!("{}", alias);
                }
            } else {
                let cmd_width = if sub.is_present("cmd_full") {
                    None
                } else if let Some(w) = sub.value_of("cmd_width") {
                    Some(w.parse::<usize>().unwrap_or(0))
                } else {
                    config.default.cmd_width
                };

                print_table(&scripts, cmd_width);
            }
        },

        ("run", Some(sub)) => {
            let path = get_config_path(config_path);
            let config = read_config(&path)
                .unwrap_or_else(|e| error_exit(&e));

            let alias = sub.value_of("alias").unwrap();
            let extra_args: Vec<&str> = sub.values_of("args").map(|v| v.collect()).unwrap_or_default();

            let script = config.scripts.get(alias)
                .unwrap_or_else(|| error_exit(&format!("AliasNotFound: No script found by alias {}", alias)));

            run_script(alias, &script.command, &extra_args, verbose);
        },

        ("remove", Some(sub)) | ("rm", Some(sub)) => {
            let path = get_config_path(config_path);
            let mut config = read_config(&path)
                .unwrap_or_else(|e| error_exit(&e));

            let alias = sub.value_of("alias").unwrap();

            if !config.scripts.contains_key(alias) {
                error_exit(&format!("AliasNotFound: No script found by alias {}", alias));
            }

            config.scripts.remove(alias);

            let content = serialize_config(&config)
                .unwrap_or_else(|e| error_exit(&e));
            fs::write(&path, content)
                .unwrap_or_else(|e| error_exit(&format!("Failed to write config: {}", e)));

            println!("Removed {}", alias);
        },

        ("show", Some(sub)) => {
            let path = get_config_path(config_path);
            let config = read_config(&path)
                .unwrap_or_else(|e| error_exit(&e));

            let alias = sub.value_of("alias").unwrap();

            let script = config.scripts.get(alias)
                .unwrap_or_else(|| error_exit(&format!("AliasNotFound: No script found by alias {}", alias)));

            println!("{}", script.command);
        },

        ("edit", Some(sub)) => {
            let path = get_config_path(config_path);
            let mut config = read_config(&path)
                .unwrap_or_else(|e| error_exit(&e));

            let alias = sub.value_of("alias").unwrap();

            if !config.scripts.contains_key(alias) {
                error_exit(&format!("AliasNotFound: No script found by alias {}", alias));
            }

            let current_cmd = config.scripts[alias].command.clone();
            let new_cmd = open_editor_with_content(&current_cmd)
                .unwrap_or_else(|e| error_exit(&e));

            if let Some(script) = config.scripts.get_mut(alias) {
                script.command = new_cmd;
            }

            let content = serialize_config(&config)
                .unwrap_or_else(|e| error_exit(&e));
            fs::write(&path, content)
                .unwrap_or_else(|e| error_exit(&format!("Failed to write config: {}", e)));

            println!("Edited {}", alias);
        },

        ("copy", Some(sub)) | ("cp", Some(sub)) => {
            let path = get_config_path(config_path);
            let mut config = read_config(&path)
                .unwrap_or_else(|e| error_exit(&e));

            let from_alias = sub.value_of("from-alias").unwrap();
            let to_alias = sub.value_of("to-alias").unwrap();

            if !config.scripts.contains_key(from_alias) {
                error_exit(&format!("AliasNotFound: No script found by alias {}", from_alias));
            }

            if config.scripts.contains_key(to_alias) {
                error_exit(&format!("AliasAlreadyExists:  {}", to_alias));
            }

            let script = config.scripts[from_alias].clone();
            config.scripts.insert(to_alias.to_string(), script);

            let content = serialize_config(&config)
                .unwrap_or_else(|e| error_exit(&e));
            fs::write(&path, content)
                .unwrap_or_else(|e| error_exit(&format!("Failed to write config: {}", e)));

            println!("Copy from alias {} to new alias {}", from_alias, to_alias);
        },

        ("move", Some(sub)) | ("mv", Some(sub)) | ("rename", Some(sub)) => {
            let path = get_config_path(config_path);
            let mut config = read_config(&path)
                .unwrap_or_else(|e| error_exit(&e));

            let from_alias = sub.value_of("from-alias").unwrap();
            let to_alias = sub.value_of("to-alias").unwrap();
            let force = sub.is_present("force");

            if !config.scripts.contains_key(from_alias) {
                error_exit(&format!("AliasNotFound: No script found by alias {}", from_alias));
            }

            if config.scripts.contains_key(to_alias) && !force {
                error_exit(&format!("AliasAlreadyExists:  {}", to_alias));
            }

            let script = config.scripts.remove(from_alias).unwrap();
            config.scripts.insert(to_alias.to_string(), script);

            let content = serialize_config(&config)
                .unwrap_or_else(|e| error_exit(&e));
            fs::write(&path, content)
                .unwrap_or_else(|e| error_exit(&format!("Failed to write config: {}", e)));

            println!("Move from alias {} to new alias {}", from_alias, to_alias);
        },

        _ => {
            // No subcommand - try to run alias directly
            if let Some(alias) = matches.value_of("alias") {
                let path = get_config_path(config_path);
                let config = read_config(&path)
                    .unwrap_or_else(|e| error_exit(&e));

                let extra_args: Vec<&str> = matches.values_of("args").map(|v| v.collect()).unwrap_or_default();

                let script = config.scripts.get(alias)
                    .unwrap_or_else(|| error_exit(&format!("AliasNotFound: No script found by alias {}", alias)));

                run_script(alias, &script.command, &extra_args, verbose);
            }
        }
    }
}

fn get_config_path(config_path: Option<PathBuf>) -> PathBuf {
    if let Some(p) = config_path {
        return p;
    }

    find_default_config()
        .unwrap_or_else(|| error_exit("No default config file found. See help for more info."))
}

fn run_script(alias: &str, command: &str, args: &[&str], verbose: bool) {
    if verbose {
        println!("Starting script \"{}\"", alias);
        println!("-------------------------");
    }

    let mut cmd = Command::new("sh");
    cmd.arg("-c").arg(command).arg("--");
    for arg in args {
        cmd.arg(arg);
    }

    let status = cmd.status()
        .unwrap_or_else(|e| error_exit(&format!("Failed to run script: {}", e)));

    if verbose {
        println!("-------------------------");
        println!("Script complete");
    }

    process::exit(status.code().unwrap_or(0));
}

fn open_editor() -> Result<String, String> {
    open_editor_with_content("")
}

fn open_editor_with_content(content: &str) -> Result<String, String> {
    let editor = env::var("EDITOR").unwrap_or_else(|_| "vi".to_string());

    // Create a temp file
    let temp_file = std::env::temp_dir().join(format!("pier_edit_{}", std::process::id()));
    fs::write(&temp_file, content)
        .map_err(|e| format!("Failed to create temp file: {}", e))?;

    let status = Command::new(&editor)
        .arg(&temp_file)
        .status()
        .map_err(|_| format!("EditorError: Failed when trying to get input from editor Failed to open `{}` as a text editor or editor was terminated with errors.", editor))?;

    if !status.success() {
        return Err(format!("EditorError: Failed when trying to get input from editor Failed to open `{}` as a text editor or editor was terminated with errors.", editor));
    }

    let result = fs::read_to_string(&temp_file)
        .map_err(|e| format!("Failed to read temp file: {}", e))?;

    let _ = fs::remove_file(&temp_file);

    Ok(result.trim().to_string())
}
